  insert into public.english_test_passages (passage_text) values ('Quick update on invoice #2148 for Harborview Consulting. The amount we sent yesterday was wrong: it showed $4,850 instead of $3,850, because a canceled design task was never removed from the billing sheet. I have already spoken with the client''s finance contact, and she has agreed to disregard the original document. Accounts will issue a corrected invoice this afternoon, and I will forward it to the client once Alex signs off. Until then, please do not record any payment against this invoice in our system. Apologies for the extra steps. — Sam') returning id into v_p;
