  insert into public.english_test_passages (passage_text) values ('Hi Jordan — quick update on the director''s trip next week. The flight to the conference is booked, and I have paid for the return ticket as well. The airport transfer is arranged for both days. The only thing still open is the hotel: they emailed to say our preferred room type is sold out, so they are checking whether a similar room is available at the same rate. They promised an answer by tomorrow morning. If they cannot confirm by then, I will book the backup hotel across the street instead. Could you hold off on sending the final itinerary until the hotel is settled?') returning id into v_p;
  insert into public.english_test_questions (section, question_text, options, correct_answer, display_order, active, passage_id) values ('comprehension', 'What is the main purpose of this message?', '["To ask a colleague to look for a cheaper flight", "To report the progress of the travel preparations", "To complain about the organization of the conference", "To request more money for the director''s hotel stay"]'::jsonb, 1, 1, true, v_p);
  insert into public.english_test_questions (section, question_text, options, correct_answer, display_order, active, passage_id) values ('comprehension', 'Which of these tasks does the writer say is already finished?', '["Reserving the hotel room for the trip", "Sending out the final itinerary", "Setting up transport to and from the airport", "Booking a room at the backup hotel"]'::jsonb, 2, 2, true, v_p);
  insert into public.english_test_questions (section, question_text, options, correct_answer, display_order, active, passage_id) values ('comprehension', 'Why is the hotel booking still unconfirmed?', '["The writer has not yet contacted the hotel", "The hotel stopped answering messages", "The room''s price rose above the agreed budget", "The room they wanted is fully booked"]'::jsonb, 3, 3, true, v_p);
