  insert into public.english_test_passages (passage_text) values ('This morning we received a complaint from the client about the quarterly report we delivered on Monday. According to their message, the section covering vendor expenses was left out of the file, even though it appears in the table of contents. After reviewing our records, we confirmed the section was written but was removed by mistake when the document was exported. Our team is adding it back now, and a corrected copy should be ready by tomorrow afternoon. Once I have approved that version, please resend it to the client with a brief apology and confirm that they received the complete file.') returning id into v_p;
